-- 읽기 전용. 설치 후 9행, 01~08 ok, 09 info. 기능 사용 이후에도 다시 실행할 수 있다.
WITH tables AS (SELECT c.oid,c.relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='teacher_roster' AND c.relkind='r'),
funcs AS (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'workhub_teacher_roster_%'),checks AS (
 SELECT 'TR1-03-01' no,'명부 표 10개·RLS' item,(SELECT count(*)=10 AND bool_and(relrowsecurity) FROM tables) pass
 UNION ALL SELECT 'TR1-03-02','API 직접 표·시퀀스 권한 없음',NOT EXISTS(SELECT 1 FROM tables CROSS JOIN(VALUES('anon'),('authenticated'),('service_role')) r(role) WHERE has_table_privilege(r.role,tables.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) AND NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN(VALUES('anon'),('authenticated'),('service_role')) r(role) WHERE n.nspname='teacher_roster' AND c.relkind='S' AND has_sequence_privilege(r.role,c.oid,'USAGE,SELECT,UPDATE'))
 UNION ALL SELECT 'TR1-03-03','공개 함수 5개·검색경로·소유자', (SELECT count(*)=5 AND bool_and(prosecdef AND 'search_path=""'=ANY(proconfig) AND pg_get_userbyid(proowner)='postgres') FROM funcs)
 UNION ALL SELECT 'TR1-03-04','인증 실행만 허용', (SELECT count(*)=5 AND bool_and(has_function_privilege('authenticated',oid,'EXECUTE') AND NOT has_function_privilege('anon',oid,'EXECUTE') AND NOT has_function_privilege('service_role',oid,'EXECUTE') AND NOT EXISTS(SELECT 1 FROM aclexplode(COALESCE(proacl,acldefault('f',proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE')) FROM funcs)
 UNION ALL SELECT 'TR1-03-05','내부 함수 직접 실행 없음',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN(VALUES('anon'),('authenticated'),('service_role')) r(role) WHERE n.nspname='teacher_roster' AND has_function_privilege(r.role,p.oid,'EXECUTE'))
 UNION ALL SELECT 'TR1-03-06','계정·명부 기간 중복 차단', (SELECT count(*)=2 FROM pg_constraint WHERE connamespace='teacher_roster'::regnamespace AND conrelid='teacher_roster.links'::regclass AND contype='x')
 UNION ALL SELECT 'TR1-03-07','연결·접수·이력 불변', (SELECT count(*)=3 AND bool_and(tgenabled='O') FROM pg_trigger WHERE tgname IN('tr1_links_immutable','tr1_requests_immutable','tr1_history_immutable') AND tgrelid IN('teacher_roster.links'::regclass,'teacher_roster.requests'::regclass,'teacher_roster.history'::regclass))
 UNION ALL SELECT 'TR1-03-08','설치 두 단계 기록', (SELECT count(*)=2 FROM teacher_roster.installs WHERE batch IN('TR1-01','TR1-02'))
)
SELECT no,item,CASE WHEN COALESCE(pass,false) THEN 'ok' ELSE 'FAIL' END status,NULL::jsonb value FROM checks
UNION ALL SELECT 'TR1-03-09','명부·편성·계정 연결','info',jsonb_build_object('teachers',(SELECT count(*) FROM teacher_roster.teachers),'drafts',(SELECT count(*) FROM teacher_roster.plans WHERE state='draft'),'published',(SELECT count(*) FROM teacher_roster.plans WHERE state='published'),'links',(SELECT count(*) FROM teacher_roster.links)) ORDER BY no;
